  cycle_nudge_reflect_mood_body: "Uma verificação rápida de humor constrói o quadro ao longo do tempo — padrões por fase são mais fáceis de ver quando você tem alguns ciclos registrados.",
  cycle_nudge_reflect_symptom_headline: "Notando *algo* hoje?",
  cycle_nudge_reflect_symptom_body: "Cólicas, seios sensíveis, uma dor de cabeça? Registrar sintomas ajuda você e seu médico a identificar o que é típico para você e o que não é.",
  cycle_nudge_reflect_energy_headline: "Onde está sua *energia*?",
  cycle_nudge_reflect_energy_body: "A energia naturalmente diminui antes de seu período. Anotar hoje ajuda você a planejar de acordo com seu próprio ritmo em vez de lutar contra ele.",
  cycle_nudge_nutrition_luteal_headline: "Procure por *magnésio*",
  cycle_nudge_nutrition_luteal_body: "Chocolate amargo, amêndoas, sementes de abóbora e bananas aliviam cólicas e estabilizam o humor na segunda metade do ciclo. Combine com carboidratos complexos para amenizar os desejos.",
  cycle_nudge_nutrition_ovulation_headline: "Alimente o *óvulo*",
  cycle_nudge_nutrition_ovulation_body: "Alimentos ricos em antioxidantes — frutas vermelhas, folhas verdes, nozes — apoiam a qualidade do óvulo. Zinco (sementes de abóbora, grão-de-bico) é mais importante próximo à ovulação.",
  cycle_nudge_edu_menstruation_headline: "Seu período é o *primeiro* dia",
  cycle_nudge_edu_menstruation_body: "O dia um do ciclo é o primeiro dia de sangramento real, não sangramento leve. É o ponto de ancoragem do qual toda previsão é contada — então registrar com precisão aguça tudo.",
  cycle_nudge_edu_follicular_headline: "Um folículo *vence*",
  cycle_nudge_edu_follicular_body: "Vários folículos começam a crescer a cada ciclo, mas geralmente apenas um amadurece e libera um óvulo. O estrogênio crescente é o que direciona essa seleção.",
  cycle_nudge_edu_ovulation_headline: "Um evento de *36 horas*",
  cycle_nudge_edu_ovulation_body: "A ovulação em si é breve — o pico de LH desencadeia a liberação em ~24–36 horas. É por isso que as tiras de LH são cronometradas para capturar o pico, não a liberação.",
  cycle_nudge_edu_luteal_headline: "A *espera de duas semanas*",
  cycle_nudge_edu_luteal_body: "A fase lútea é notavelmente estável — geralmente 12–14 dias independentemente do comprimento do ciclo. A maioria da variação do ciclo vem da primeira metade, não desta.",
  cycle_pillar_fertility: "Noções Básicas de Fertilidade",
