  dataInv_exportBtn: "Exportar todos os meus dados",
  dataTrans_title: "Como usamos seus dados",
  dataTrans_subtitle: "em linguagem simples",
  dataTrans_intro: "Você nos confia informações sensíveis. Aqui está exatamente o que coletamos e por quê — e, tão importante quanto, o que nunca faremos com elas.",
  dataTrans_sectionCollect: "O que coletamos e por quê",
  dataTrans_healthTitle: "Dados de saúde e ciclo",
  dataTrans_healthBody: "Menstruações, sintomas, semanas de gravidez, peso e humor — usados só para o seu acompanhamento, seus insights e a orientação da Grandma. Continuam sendo seus.",
  dataTrans_childTitle: "Informações dos filhos",
  dataTrans_childBody: "Nomes, datas de nascimento, crescimento, alimentação, sono e registros médicos — usados para personalizar a jornada do seu filho e compartilhar com o círculo de cuidado que você escolher.",
  dataTrans_accountTitle: "Dados da conta",
  dataTrans_accountBody: "Seu e-mail e login servem para proteger sua conta e sincronizar seus dados entre aparelhos. Nada além disso.",
  dataTrans_aiTitle: "Conversas com a Grandma",
  dataTrans_aiBody: "Suas perguntas dão contexto para a Grandma responder bem. Você pode desligar o uso de dados pela IA e apagar seu histórico de conversas quando quiser.",
  dataTrans_photosTitle: "Fotos e escaneamentos",
  dataTrans_photosBody: "As fotos que você adiciona às memórias ou escaneia para insights ficam guardadas de forma privada para você e só são compartilhadas com seu círculo de cuidado quando você permitir.",
  dataTrans_usageTitle: "Uso do app",
  dataTrans_usageBody: "O uso anônimo e agregado nos ajuda a corrigir erros e melhorar o app. Você pode desativar em Dados e privacidade → Análises.",
  dataTrans_sectionNever: "Nós nunca",
  dataTrans_never1: "Vendemos seus dados pessoais a ninguém.",
  dataTrans_never2: "Compartilhamos seus dados de saúde ou dos seus filhos sem o seu consentimento.",
  dataTrans_never3: "Usamos seus dados privados para treinar IA de terceiros.",
  dataTrans_never4: "Mantemos seus dados depois que você exclui a conta.",
  dataTrans_footer: "Seus dados são criptografados em repouso e em trânsito. Leia a Política de Privacidade completa quando quiser em Dados e privacidade → Legal.",
  about_title: "Sobre o grandma.app",
  about_tagline: "sua companheira de confiança",
  about_missionTitle: "Nossa missão",
  about_missionBody: "Ser a presença calma e sábia ao lado de cada mãe e pai — desde a tentativa, passando pela gravidez, até os primeiros anos. Apoio que parece família.",
  about_expertiseTitle: "Baseado em especialistas",
  about_expertiseBody: "A orientação da Grandma se apoia em conhecimento de obstetras, parteiras e pediatras. É um apoio cuidadoso — nunca um substituto para o seu médico.",
  about_privacyTitle: "Privacidade em primeiro lugar",
  about_privacyBody: "Seus dados de saúde e da família são seus. Veja exatamente o que coletamos e por quê.",
  about_privacyPolicy: "Política de Privacidade",
  about_terms: "Termos de Uso",
  about_help: "Ajuda e perguntas frequentes",
  about_contact: "Fale com a gente",
  about_copyright: "© 2026 grandma.app. Feito com carinho.",
  help_title: "Ajuda e perguntas frequentes",
  help_subtitle: "estamos aqui por você",
  help_searchPlaceholder: "O que você gostaria de encontrar?",
  help_noResults: "Nenhuma resposta encontrada. Tente outras palavras ou fale com a gente abaixo.",
  help_stillStuck: "Ainda precisa de uma mãozinha?",
  help_stillStuckBody: "Não achou sua resposta? Nossa equipe adora ajudar.",
  help_contactUs: "Fale com a gente",
  help_catStart: "Primeiros passos",
  help_catAccount: "Conta e dados",
  help_catCare: "Círculo de Cuidados",
  help_catAi: "Grandma IA",
  help_catBilling: "Assinaturas e cobrança",
  help_catPrivacy: "Privacidade",
  help_q_modes: "O que são os modos de jornada?",
  help_a_modes: "O grandma.app se adapta ao momento que você vive: Ciclo (acompanhar seu ciclo ou tentar engravidar), Gravidez, Filhos (de 0 a 5 anos) e Menopausa. Cada jornada muda sua tela inicial, o que você registra e a orientação da Grandma.",
  help_q_switchMode: "Como troco de modo?",
  help_a_switchMode: "Abra a aba Ajustes e toque em uma jornada em Minha Jornada. Cada jornada guarda os próprios dados, então nada se perde ao trocar.",
  help_q_logging: "Como registro algo?",
  help_a_logging: "Registre pela tela inicial ou pela aba Calendário — escolha o dia e o que anotar: menstruação, sintomas, humor, sono e mais. Tudo aparece no calendário e nas suas Notas.",
  help_q_export: "Como exporto meus dados?",
  help_a_export: "Vá em Ajustes → Dados e privacidade → Dados que guardamos → Exportar todos os meus dados. Você recebe uma cópia completa em JSON, legível por máquina, de tudo que guardamos.",
  help_q_delete: "Como excluo minha conta?",
  help_a_delete: "Ajustes → Conta → Excluir conta. Isso apaga seus dados dos nossos sistemas de forma permanente e não pode ser desfeito.",
  help_q_password: "Como altero minha senha?",
  help_a_password: "Ajustes → Conta → Alterar senha. Se você entrou com Apple ou Google, gerencie o login por esse provedor.",
  help_q_invite: "Como convido meu círculo de cuidado?",
  help_a_invite: "Ajustes → Círculo de Cuidado → Convidar. Envie um link seguro para um parceiro, babá ou avó/avô. Eles entram com exatamente as permissões que você escolher.",
  help_q_permissions: "Posso controlar o que os cuidadores veem?",
  help_a_permissions: "Pode. Cada cuidador tem permissões definidas por você — você decide quem pode ver ou adicionar registros, dados de saúde e mais. Mude ou revogue o acesso quando quiser.",
  help_q_grandma: "Quem é a Grandma?",
  help_a_grandma: "A Grandma é sua companheira de IA, movida por Claude. Ela responde com o contexto da sua jornada e oferece orientação acolhedora e prática, de dia ou de noite.",
  help_q_medical: "O conselho da Grandma é orientação médica?",
  help_a_medical: "Não. A Grandma oferece orientação cuidadosa e educativa — não diagnóstico nem tratamento. Para dúvidas de saúde, consulte sempre seu médico, parteira ou pediatra.",
  help_q_premium: "O que o Premium inclui?",
  help_a_premium: "O Premium libera escaneamentos e conversas ilimitados, insights completos e lembretes. Você pode assinar por mês ou por ano.",
  help_q_cancel: "Como cancelo o Premium?",
  help_a_cancel: "Gerencie ou cancele sua assinatura quando quiser nos ajustes da conta da loja de apps. Os recursos Premium continuam ativos até o fim do período de cobrança.",
  help_q_dataSafe: "Meus dados estão seguros?",
  help_a_dataSafe: "Sim. Seus dados são criptografados em trânsito e em repouso e protegidos por segurança em nível de linha, para que só você e o círculo de cuidado que escolher tenham acesso.",
  help_q_sell: "Vocês vendem meus dados?",
  help_a_sell: "Nunca. Não vendemos seus dados pessoais e jamais usamos seus dados privados de saúde ou dos seus filhos para treinar IA de terceiros.",
  legal_contents: "Conteúdo",
  legal_hostedPrefix: "Veja a política completa em",
