  safety_reason_other: "Outro motivo",
  guidelines_title: "Diretrizes da comunidade",
  guidelines_subtitle: "um lugar gentil para compartilhar",
  guidelines_intro: "O grandma.app é um espaço para mães e pais se apoiarem com sinceridade. Para mantê-lo seguro para todos, pedimos que você siga algumas regras simples.",
  guidelines_rule1Title: "Seja gentil e respeitosa",
  guidelines_rule1Body: "Cada pessoa aqui está na sua própria jornada. Sem assédio, bullying, discurso de ódio ou ataques pessoais.",
  guidelines_rule2Title: "Proteja a privacidade",
  guidelines_rule2Body: "Não compartilhe informações pessoais ou de saúde de outras pessoas. Pense também no que você revela sobre a sua própria família.",
  guidelines_rule3Title: "Ofereça apoio, não diagnóstico",
  guidelines_rule3Body: "Compartilhe experiência e incentivo — não orientações médicas. Para dúvidas de saúde, indique sempre o médico.",
  guidelines_rule4Title: "Sem spam nem vendas",
  guidelines_rule4Body: "Mantenha a comunidade para a conexão, não para a divulgação. Anúncios do mercado ficam na troca, não no feed.",
  guidelines_rule5Title: "Mantenha tudo seguro",
  guidelines_rule5Body: "Sem conteúdo que incentive automutilação, perigo para crianças ou qualquer coisa ilegal. Removemos e podemos suspender a conta.",
  guidelines_sectionReport: "Se você ver algo",
  guidelines_reportBody: "Mantenha pressionado qualquer post ou mensagem para denunciar ou bloquear a pessoa. As denúncias são privadas e analisadas pela nossa equipe. Em uma emergência, ligue sempre para os serviços de emergência locais.",
  guidelines_footer: "Quebrar essas regras pode levar à remoção de conteúdo ou à suspensão da conta. Obrigada por manter esta comunidade segura.",
