  sw2_leap19_name: "Eventos",
  sw2_leap19_desc: "Entender que as ações acontecem em sequência",
  sw2_leap19_brain: "Por volta dessa fase, os bebês costumam começar a perceber o mundo como uma série de acontecimentos, e não como um grande borrão. As ações têm começo, meio e fim. É o início do pensamento de causa e efeito, e por isso tudo pode parecer tão fascinante de repente.",
  sw2_leap19_tip: "Brinque de causa e efeito, como esconde-esconde — o bebê está aprendendo que os acontecimentos têm resultados previsíveis.",
  sw2_leap19_ph0: "Grudado, chora quando é colocado no chão, sono agitado. O bebê pode ficar cansado com tanta novidade ao mesmo tempo.",
  sw2_leap19_ph1: "O bebê costuma estar ocupado ligando cada ação ao que acontece depois — empurrando, soltando, observando de perto.",
  sw2_leap19_ph2: "Surge o alcance intencional, junto com os primeiros sinais de permanência do objeto — o bebê procura o que caiu.",
  sw2_leap19_sg0: "Mais angústia ao se separar",
  sw2_leap19_sg1: "Muito grudado",
  sw2_leap19_sg2: "Chora quando o brinquedo cai",
  sw2_leap19_sg3: "Resiste às sonecas",
  sw2_leap19_sg4: "Pede interação o tempo todo",
  sw2_leap19_sg5: "Fica irritado quando a rotina muda",
  sw2_leap19_sk0: "Alcança e pega de propósito",
  sw2_leap19_sk1: "Sacode e bate os brinquedos",
  sw2_leap19_sk2: "Reconhece brincadeiras",
  sw2_leap19_sk3: "Entende \"em cima\" e \"embaixo\"",
  sw2_leap19_sk4: "Acompanha objetos em movimento com os olhos",
  sw2_leap19_sk5: "Ri com surpresas",
  sw2_leap19_ac0: "Esconde-esconde e brincadeiras de achar",
  sw2_leap19_ac1: "Rolar uma bola de um para o outro",
  sw2_leap19_ac2: "Brinquedos simples de causa e efeito (apertou = som)",
  sw2_leap19_ac3: "Narre a rotina do dia passo a passo",
  sw2_leap5_name: "Sensações em mudança",
  sw2_leap5_desc: "O bebê descobre um mundo mais rico de sentidos",
  sw2_leap5_brain: "Por volta dessa fase, seu bebê pode começar a perceber muito mais detalhes pelos sentidos: imagens mais nítidas, sons mais ricos, novas sensações no corpo. Pode parecer muita coisa e, ao mesmo tempo, maravilhoso.",
  sw2_leap5_ph0: "Mais choro, mais apego e sono agitado são comuns. O bebê pode estar recebendo muita informação sensorial nova.",
  sw2_leap5_ph1: "O bebê está absorvendo muitas imagens e sons novos. A irritação pode ter um pico antes de acalmar.",
  sw2_leap5_ph2: "A nova percepção dos sentidos floresce: você vai notar períodos de alerta mais longos e um olhar mais intencional.",
  sw2_leap5_sg0: "Chora mais do que o normal",
  sw2_leap5_sg1: "Quer mamar o tempo todo",
  sw2_leap5_sg2: "Mais difícil de acalmar",
  sw2_leap5_sg3: "Prefere ficar pertinho",
  sw2_leap5_sg4: "Se assusta com mais facilidade",
  sw2_leap5_sg5: "Não gosta de ficar sem roupa",
  sw2_leap5_sk0: "Reage a luz e som",
  sw2_leap5_sk1: "Acompanha objetos com o olhar de forma mais suave",
  sw2_leap5_sk2: "Primeiros sorrisos sociais",
  sw2_leap5_sk3: "Mais períodos de alerta",
  sw2_leap5_sk4: "Vira em direção à sua voz",
  sw2_leap5_sk5: "Percebe padrões de alto contraste",
  sw2_leap5_ac0: "Segure o bebê virado para fora para explorar o ambiente",
  sw2_leap5_ac1: "Mostre cartões em preto e branco de alto contraste",
  sw2_leap5_ac2: "Conte em voz alta tudo o que você faz",
  sw2_leap5_ac3: "Massagem suave no bebê nos momentos de calma",
  sw2_leap5_tip: "O contato pele a pele é muito valioso agora. Usar sling e embalar com carinho podem aliviar os dias mais agitados.",
