  sw1_pa_movementGuide: "Um guia de movimento leve",
  sw1_pa_exT1: "Muitas diretrizes sugerem cerca de 150 minutos de movimento moderado por semana, e seu profissional de saúde pode adaptar isso a você. A energia pode cair no início — caminhadas curtas contam.",
  sw1_pa_exT2: "Muitas diretrizes sugerem cerca de 150 minutos de movimento moderado por semana, e seu profissional de saúde pode adaptar isso a você. Natação, ioga para gestantes e caminhadas podem ser muito gostosas agora.",
